SELECT id, code, name, timezone, state, version
FROM warehouse
WHERE enterprise_id = #{enterpriseId} AND id = #{warehouseId}

SELECT id, code, name, timezone, state, version
FROM warehouse
WHERE enterprise_id = #{enterpriseId} AND code = #{code}

SELECT id, code, zone_code, location_type, capacity_qty, capacity_unit, state, version
FROM location
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId} AND id = #{locationId}

SELECT id, code, zone_code, location_type, capacity_qty, capacity_unit, state, version
FROM location
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId} AND code = #{code}

SELECT id, location_id, state, reason_code, fence_epoch, count_plan_id, version
FROM location_gate
WHERE enterprise_id = #{enterpriseId} AND warehouse_id = #{warehouseId} AND location_id = #{locationId}

SELECT id, sku_id, unit_code, numerator, denominator, policy_version, version
FROM sku_unit
WHERE enterprise_id = #{enterpriseId} AND sku_id = #{skuId} AND unit_code = #{unitCode}

SELECT request_digest, resource_id
FROM write_idempotency
WHERE enterprise_id = #{enterpriseId}
  AND warehouse_id = #{warehouseId}
  AND client_operation_id = #{clientOperationId}
